input.script:
() => { 
  const cb = document.querySelector('input[type="checkbox"]');
  if (!cb) return 'checkbox not found';
  const rect = cb.getBoundingClientRect();
  cb.click();
  return JSON.stringify({found: true, rect: {x: rect.x, y: rect.y, w: rect.width, h: rect.height}, checked: cb.checked});
}

() => { 
  const cb = document.querySelector('input[type="checkbox"]');
  if (!cb) return 'checkbox not found';
  // Try multiple event dispatch methods
  ['mousedown', 'mouseup', 'click'].forEach(eventType => {
    cb.dispatchEvent(new MouseEvent(eventType, {bubbles: true, cancelable: true, view: window}));
  });
  return JSON.stringify({checked: cb.checked, ariaLabel: cb.getAttribute('aria-label')});
}

() => { 
  const cb = document.querySelector('input[type="checkbox"]');
  return JSON.stringify({
    found: !!cb,
    checked: cb ? cb.checked : null,
    rect: cb ? cb.getBoundingClientRect() : null,
    visible: cb ? (cb.offsetWidth > 0 && cb.offsetHeight > 0) : null
  });
}

async () => {
  const cb = document.querySelector('input[type="checkbox"]');
  if (!cb) return 'no checkbox';
  // Force a real click sequence
  const rect = cb.getBoundingClientRect();
  const cx = rect.left + rect.width/2;
  const cy = rect.top + rect.height/2;
  for (const evt of ['pointerdown','mousedown','pointerup','mouseup','click']) {
    cb.dispatchEvent(new MouseEvent(evt, {bubbles: true, cancelable: true, view: window, clientX: cx, clientY: cy, button: 0}));
  }
  await new Promise(r => setTimeout(r, 3000));
  return JSON.stringify({checked: cb.checked, url: location.href});
}
